-- The two checklists published on 2026-10-24: The Paperwork After a Death
-- (Affairs) and Turning the Noise Down on Your Phone (Screens).
-- Generated by `python3 tools/checklists_sql.py --since 2026-10-24`; the repo
-- copy in data/checklists.json is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('the-paperwork-after-a-death', 'The Paperwork After a Death', 'For the weeks of paperwork that follow a death, when the forms arrive faster than the grief allows. It gets the certificates and the account list in one place, holds the pace to one call a day, and postpones every decision that can wait.', 'Affairs', '["Get ten copies of the death certificate — almost every office wants one of its own.", "Make one list of every account and policy — the hunting is the part that exhausts people.", "Tell the bank and the pension first — those two unlock or freeze most of the rest.", "Do one call a day, not six — each one costs more than it looks like it will.", "Keep a notebook by the phone — names, dates and reference numbers you will need twice.", "Let someone else make the calls you dread — a friend can say the sentence you cannot.", "Say no to any decision that can wait — the house and the clothes are not this month''s job.", "Expect a form to undo you — grief does not wait for a convenient moment.", "Call or text 988 if it gets too heavy — the Suicide and Crisis Lifeline answers day and night."]'::jsonb, 'weekly', array['Grief', 'Stress']::text[], 1, '2026-10-24T16:00:00+00:00'::timestamptz),
  ('turning-the-noise-down-on-your-phone', 'Turning the Noise Down on Your Phone', 'For when the phone is running your attention rather than the other way around. It turns off the notifications that are not people, moves the worst apps off the first screen, puts the charger outside the bedroom, and keeps one hour a day free of it.', 'Screens', '["Turn off every notification but calls and texts — the rest can wait until you look.", "Take the badge counts off the icons — a red number is a job you did not ask for.", "Move the two worst apps off the first screen — a second of friction does most of the work.", "Charge it outside the bedroom tonight — the phone by the bed decides both ends of your day.", "Set one hour a day with no phone in it — dinner or the walk, the same hour each day.", "Turn the screen to black and white for a week — color is doing more of the pulling than you think.", "Unfollow five accounts that leave you flat — the feed is a room you choose the people in.", "Look at the weekly screen time once — the number is information, not a telling-off."]'::jsonb, 'weekly', array['Habits', 'Sleep']::text[], 1, '2026-10-24T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
